FIELDS = ["source", "name", "website", "asof_date", "category", "htgf_relevant", "reason"]

def main():
    rows = []
    for path in sorted(glob.glob("raw/cohort_*.csv")):
        if path.endswith("cohort_utum_sample.csv"):
            continue
        with open(path, encoding="utf-8-sig", newline="") as f:
            for row in csv.DictReader(f):
                if not (row.get("asof_date") or "").strip():
                    continue
                key = (row.get("source", ""), row.get("name", ""))
                category, relevance, reason = DECISIONS[key]
                rows.append({"source": key[0], "name": key[1], "website": row.get("website", ""),
                             "asof_date": row["asof_date"], "category": category,
                             "htgf_relevant": relevance, "reason": reason})
    with open("raw/relevance.csv", "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=FIELDS)
        writer.writeheader()
        writer.writerows(rows)
    for label, subset in [("overall", rows)] + [(s, [r for r in rows if r["source"] == s]) for s in sorted({r["source"] for r in rows})]:
        print(f"\n{label} ({len(subset)})")
        print("category:", dict(sorted(Counter(r["category"] for r in subset).items())))
        print("htgf_relevant:", dict(sorted(Counter(r["htgf_relevant"] for r in subset).items())))

if __name__ == "__main__":
    main()
